package api

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"strings"
	"time"

	"entire.io/core/authn"
	"entire.io/core/cluster"
	"entire.io/core/githubperms"
	"entire.io/core/identity"
	"entire.io/core/mirrorrepo"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/mirrorvis"
	"entire.io/core/model"
	"entire.io/core/permssnapshotter"
	"entire.io/core/regional"
	"entire.io/core/repoadmin"
	"entire.io/core/resource"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
	"go.opentelemetry.io/otel"
)

// tracerName scopes the manual spans this package opens around the synchronous
// phases of a mirror op. Mirror create chains several remote round-trips
// (cluster resolve, GitHub App calls, SpiceDB writes, a cross-plane provision)
// before it returns; without per-phase spans a slow create collapses into one
// opaque request span and the latency can't be attributed. The phase spans are
// siblings under the request span — each is opened from the request ctx and
// ended before the next begins.
const tracerName = "entire.io/core/api"

// defaultGitHubAppPublicURL is the prod GitHub App install page. It's the
// fallback for the GITHUB_APP_PUBLIC_URL override (staging points at its own
// App); see Server.githubAppPublicURL.
const defaultGitHubAppPublicURL = "https://github.com/apps/entire"

// appInstallURL is the public "install the App" URL surfaced to users.
// Empty override → prod default.
func (s *Server) appInstallURL() string {
	if s.githubAppPublicURL != "" {
		return s.githubAppPublicURL
	}
	return defaultGitHubAppPublicURL
}

// errAppNotInstalled is the verbatim, user-facing string the CLI prints
// when mirror create bounces because the App can't see the upstream. The
// link points at the install page so the user can install in one click
// instead of hunting the marketplace. Several branches return it; keep it a
// single source of truth so the tests that match it verbatim and the
// NotContains guards on the 502 paths stay honest.
func (s *Server) errAppNotInstalled() string {
	return "app not installed on the upstream account; install at " + s.appInstallURL() + " then retry"
}

// errMirrorRepoInaccessible is the single, existence-agnostic 404 the user
// mirror-create path returns whenever it cannot mirror a repo for the caller —
// whether the repo does not exist, the App is not installed with access to it,
// or the caller lacks read access. Folding all of these into one byte-identical
// response is what closes the ENT-1021 enumeration oracle: a caller without read
// access can no longer distinguish an existing private repo from a missing one.
// The admin (operator) path has no caller gate to conflate, so it keeps the
// honest errAppNotInstalled surface.
func (s *Server) errMirrorRepoInaccessible() *MirrorOpError {
	return &MirrorOpError{
		Status:  http.StatusNotFound,
		Message: "cannot mirror this repository: it may not exist, the Entire App may not be installed with access to it, or you may not have read access — install/configure the App at " + s.appInstallURL() + " then retry",
	}
}

// mirrorOpRequest holds the upstream coords + target cluster the
// CreateMirrorPlacement / DeleteMirrorPlacement orchestration shares.
// ClusterHost is the data-plane host the caller wants to talk to (e.g.
// "royalcanin.partial.to") — resolved to the internal cluster slug
// before any storage write. validate() runs the shape checks both
// operations need.
type mirrorOpRequest struct {
	Provider    string
	Owner       string
	Repo        string
	ClusterHost string
}

// validate runs the shared shape checks. Returns the canonical lower-
// cased owner/repo so the URL stored in github_mirror_repo_urls
// matches regardless of the case the caller typed. GitHub coords are
// case-insensitive on the upstream side, but the STS exchange does an
// exact slug match against the persisted URL, so any casing drift
// between create-time and exchange-time would 404 the mirror.
func (r *mirrorOpRequest) validate() (owner, repo string, status int, err error) {
	if r.Provider == "" {
		return "", "", http.StatusBadRequest, errors.New("provider is required")
	}
	if r.Provider != mirrorrepo.ProviderGitHub {
		return "", "", http.StatusBadRequest, fmt.Errorf("unsupported provider %q", r.Provider)
	}
	if r.Owner == "" || r.Repo == "" {
		return "", "", http.StatusBadRequest, errors.New("owner and repo are required")
	}
	if r.ClusterHost == "" {
		return "", "", http.StatusBadRequest, errors.New("cluster_host is required")
	}
	return strings.ToLower(strings.TrimSpace(r.Owner)), strings.ToLower(strings.TrimSpace(r.Repo)), 0, nil
}

// MirrorOpError is a transport-agnostic failure from the mirror
// create/delete orchestration. CreateMirrorPlacement / DeleteMirrorPlacement
// return it so callers (coreapi's huma layer) map Status to their own
// error envelope without this package importing huma. HomeCoreURL /
// Jurisdiction are populated only for the StatusMisdirectedRequest (421)
// cross-jurisdiction redirect; Message is the caller-facing text.
type MirrorOpError struct {
	Status       int
	Message      string
	HomeCoreURL  string
	Jurisdiction string
}

func (e *MirrorOpError) Error() string { return e.Message }

// CreateMirrorResult is the success payload of CreateMirrorPlacement.
// Created distinguishes a fresh insert (201) from a re-create that found
// the existing placement (200). Suspended is true when the (re-created)
// placement carries an admin suspension (suspended_at IS NOT NULL) — always
// false on a fresh insert, since suspension is operator-applied after the fact.
type CreateMirrorResult struct {
	MirrorID  string
	MirrorURL string
	PublicURL string
	Created   bool
	Suspended bool
}

// jurisdictionRedirect returns a 421 MirrorOpError when the caller
// targeted a cluster outside this core's jurisdiction, so the orchestration
// can stop before any DB or SpiceDB write happens. The error carries
// home_core_url so the CLI can re-POST to the home core. The user's
// existing login JWT is audienced for the source region and the home core
// will refuse it as cross-juris; the CLI's crossJurisRoundTripper recovers
// by exchanging at the home core's /oauth/token for a local-audience
// token. See ADR 20260520-cross-juris-token-exchange.md.
//
// Mirror provisioning is jurisdiction-bound because entire-core's
// repoadmin.Router is built from clustersInJurisdiction at startup
// (internal/entirecore/repo_provisioner.go) — the foreign data plane
// is intentionally unreachable from this core. Falling through to the
// router would surface as a 502 *after* writing the mirror_repos row
// and SpiceDB grant, stranding both for the reconciler to retry against
// a router that will never have a client.
//
// Returns nil when the jurisdiction matches (or is empty — defensive:
// resolveClusterHost rejects empty jurisdiction already, so that branch
// is dead outside tests).
func (s *Server) jurisdictionRedirect(clusterJurisdiction string) *MirrorOpError {
	if clusterJurisdiction == "" || s.jurisdiction == "" || clusterJurisdiction == s.jurisdiction {
		return nil
	}
	homeURL := s.jurisdictionAuthHosts[clusterJurisdiction]
	if homeURL == "" {
		// jurisdictionAuthHosts is populated from the same fixture that
		// names the cluster's jurisdiction — a missing entry is operator
		// misconfig, not a client problem, so 500 makes it visible in
		// dashboards instead of looking like a routine 4xx.
		return &MirrorOpError{
			Status:  http.StatusInternalServerError,
			Message: fmt.Sprintf("cluster jurisdiction %q has no auth host wired on this core", clusterJurisdiction),
		}
	}
	return &MirrorOpError{
		Status:       http.StatusMisdirectedRequest,
		Message:      fmt.Sprintf("cluster is in jurisdiction %q; retry against the home core", clusterJurisdiction),
		HomeCoreURL:  homeURL,
		Jurisdiction: clusterJurisdiction,
	}
}

// resolveClusterHost maps the caller-supplied cluster_host to its
// internal slug + jurisdiction + public URL. Decommissioned and
// unknown hosts both surface as 400; this is the same envelope STS
// uses on ClusterURLByHost so a misconfigured CLI command can't
// tell the two apart without context. Jurisdiction is required to
// compose the gitjobs subject (mirror.git.v1.<jur>.<cluster>.…), so
// we surface it here rather than re-fetching the cluster row at the
// call site.
func (s *Server) resolveClusterHost(ctx context.Context, host string) (slug, jurisdiction, publicURL string, status int, err error) {
	if s.jurCaps == nil {
		return "", "", "", http.StatusServiceUnavailable, errors.New("cluster registry not configured")
	}
	c, err := s.cluster.GetByPublicHost(ctx, host)
	if err != nil {
		if errors.Is(err, cluster.ErrNotFound) {
			return "", "", "", http.StatusBadRequest, fmt.Errorf("unknown cluster_host %q", host)
		}
		return "", "", "", http.StatusInternalServerError, fmt.Errorf("resolve cluster: %w", err)
	}
	if c.Slug == "" || c.PublicURL == "" || c.Jurisdiction == "" {
		return "", "", "", http.StatusServiceUnavailable, fmt.Errorf("cluster %q not fully configured", host)
	}
	return c.Slug, c.Jurisdiction, c.PublicURL, 0, nil
}

// requireGitHubUser resolves the caller's account → github_user_id.
// Returns 401 when no linked GitHub handle (the WorkOS-only sign-in
// path that never linked a provider). Any other failure is 500.
func (s *Server) requireGitHubUser(ctx context.Context, claims *authn.Claims) (githubUserID int64, status int, err error) {
	if s.identity == nil {
		return 0, http.StatusServiceUnavailable, errors.New("identity service not configured")
	}
	id, _, err := s.identity.GitHubHandleForAccount(ctx, claims.AccountID)
	if err != nil {
		if errors.Is(err, identity.ErrNotFound) {
			return 0, http.StatusUnauthorized, errors.New("account has no linked GitHub identity; sign in with GitHub to mirror repos")
		}
		return 0, http.StatusInternalServerError, fmt.Errorf("resolve github user id: %w", err)
	}
	return id, 0, nil
}

// lookupGitHubRepoID translates upstream coords to the github_repo_id
// we key on. Returns 404 when no github_repos row exists for the
// (owner, repo) pair — meaning the App isn't installed on the
// upstream. Enumeration safety lives at the caller: the real CanPull
// against the user's githubUserID also collapses "denied" into the
// same 404, so public coords for a private repo never reveal which
// of the two doors the request bounced off.
func (s *Server) lookupGitHubRepoID(ctx context.Context, owner, repo string) (int64, int, error) {
	if s.githubPerms == nil {
		return 0, http.StatusServiceUnavailable, errors.New("github perms service not configured")
	}
	id, err := s.githubPerms.LookupRepoIDByCoords(ctx, owner, repo)
	if err != nil {
		if errors.Is(err, githubperms.ErrRepoNotKnown) {
			return 0, http.StatusNotFound, errors.New(s.errAppNotInstalled())
		}
		return 0, http.StatusInternalServerError, fmt.Errorf("github perms lookup: %w", err)
	}
	return id, 0, nil
}

// CreateMirrorPlacement registers a GitHub mirror on the cluster behind
// clusterHost and provisions it on the data plane. It is the single
// source of truth for mirror creation; coreapi's POST /api/v1/mirrors is
// a thin huma adapter over it. Returns a *MirrorOpError on any failure,
// with Status set to the HTTP status the caller should surface.
//
// Steps:
//
//  1. Auth the caller and resolve their github_user_id.
//  2. Resolve cluster_host to slug + public URL.
//  3. EnsureRepoKnown: establish the installation + github_repos rows
//     from the App's credential (App-JWT installation lookup →
//     installation-token repo fetch). Writes no access edges. Stamps the
//     installation_id step 6 needs and lets the upstream-account lookup
//     in step 4 resolve on a cold repo.
//  4. Authorize + resolve the parent-project owner
//     (authorizeUserMirrorCreate): a user-owned upstream may only be
//     mirrored by its GitHub owner; an org-owned one requires a live
//     GitHub repo-read check (App installation token, COR-493), and the
//     COR-432 org link is created on first mirror when missing (org-admin-gated).
//  5. CreateOrFindMirrorsProject — lazily provision the per-cluster
//     mirrors project the mirror will hang off (COR-433).
//  6. mirrorrepo.Create — writes mirror_repos + URL + SpiceDB grant.
//  7. repoadmin.Router.Provision — gives entire-server the local
//     repo_urls row that the data plane's /gh/<owner>/<repo> handler
//     resolves to the mirror ULID.
//  8. grantMirrorCreator — seed the creator's SpiceDB repo grant (the
//     gate STS reads), at the role they hold on GitHub.
func (s *Server) CreateMirrorPlacement(ctx context.Context, claims *authn.Claims, provider, owner, repo, clusterHost string) (*CreateMirrorResult, error) {
	if claims == nil {
		return nil, &MirrorOpError{Status: http.StatusUnauthorized, Message: "unauthenticated"}
	}
	if s.mirrorRepos == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror service not configured"}
	}
	if s.repoBridge == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "data plane bridge not configured"}
	}

	req := mirrorOpRequest{Provider: provider, Owner: owner, Repo: repo, ClusterHost: clusterHost}
	owner, repo, status, err := req.validate()
	if err != nil {
		return nil, &MirrorOpError{Status: status, Message: err.Error()}
	}

	stepCtx, span := otel.Tracer(tracerName).Start(ctx, "mirror.create.resolve_cluster_host")
	clusterSlug, jurisdiction, publicURL, status, err := s.resolveClusterHost(stepCtx, clusterHost)
	span.End()
	if err != nil {
		return nil, &MirrorOpError{Status: status, Message: err.Error()}
	}
	if oe := s.jurisdictionRedirect(jurisdiction); oe != nil {
		return nil, oe
	}

	stepCtx, span = otel.Tracer(tracerName).Start(ctx, "mirror.create.require_github_user")
	githubUserID, status, err := s.requireGitHubUser(stepCtx, claims)
	span.End()
	if err != nil {
		return nil, &MirrorOpError{Status: status, Message: err.Error()}
	}

	// Establish the installation + github_repos rows from the App's own
	// credential. This stamps the installation_id finishMirrorPlacement
	// needs and lets the upstream-account lookup in authorizeUserMirrorCreate
	// resolve on a cold repo — without writing any access edges (mirror authz
	// is SpiceDB now, COR-437). It does NOT gate on the caller: that's
	// authorizeUserMirrorCreate's job, below.
	if s.githubPerms == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "github perms service not configured"}
	}
	if s.ghAppCaps == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror bootstrapper not configured"}
	}
	stepCtx, span = otel.Tracer(tracerName).Start(ctx, "mirror.create.ensure_repo_known")
	githubRepoID, isPrivate, err := s.ghAppCaps.Bootstrapper.EnsureRepoKnown(stepCtx, owner, repo, time.Now())
	span.End()
	if err != nil {
		// hideExistence: the user path has a caller gate below, so the App's
		// own view of the repo must not leak existence (ENT-1021).
		return nil, s.mapBootstrapError(ctx, owner, repo, err, true)
	}

	// Authorize the create and resolve the parent mirrors-project owner: a
	// user-owned upstream may only be mirrored by its GitHub owner, and an
	// org-owned upstream requires a live GitHub repo-read check plus an
	// existing org link.
	stepCtx, span = otel.Tracer(tracerName).Start(ctx, "mirror.create.authorize")
	projectOwner, seedRole, oerr := s.authorizeUserMirrorCreate(stepCtx, claims, githubUserID, owner, repo)
	span.End()
	if oerr != nil {
		return nil, oerr
	}

	// Seed the creator's grant on the now-native mirror at the level they
	// actually hold on GitHub (writer for push, reader for pull-only) — the
	// authorize step already resolved this. The SpiceDB half rides inside the
	// placement's RepoCreated write (one round trip to the remote authz-writer
	// instead of two — the writer lives in the primary region, so a far
	// regional core pays a full cross-region RTT per write). Only the user
	// path seeds — AdminCreateMirrorPlacement mirrors repos the operator
	// doesn't own, so it implies no human grant.
	seed := &regional.SeedGrant{GranteeType: "account", GranteeID: model.ID(claims.AccountID.String()), Role: seedRole}

	stepCtx, span = otel.Tracer(tracerName).Start(ctx, "mirror.create.finish_placement")
	result, err := s.finishMirrorPlacement(stepCtx, owner, repo, clusterHost, clusterSlug, jurisdiction, publicURL, githubRepoID, isPrivate, projectOwner, seed)
	span.End()
	if err != nil {
		return nil, err
	}

	// Record the grant's bookkeeping row (repo_permissions). Enforcement
	// (SpiceDB) was already written atomically with the placement above, so a
	// failure here can't lock the creator out — it only leaves the
	// collaborators listing behind until a retried create or the reconciler
	// re-records it.
	stepCtx, span = otel.Tracer(tracerName).Start(ctx, "mirror.create.record_grant")
	oe := s.recordMirrorCreatorGrant(stepCtx, claims.AccountID, result.MirrorID, seedRole)
	span.End()
	if oe != nil {
		return nil, oe
	}

	// Backfill the rest of the upstream's collaborators into SpiceDB
	// asynchronously: enqueue a durable perms_backfill job that the in-region
	// consumer drains OFF this request path. The caller already holds their own
	// grant (grantMirrorCreator, above) and can clone immediately; the backfill
	// materialises everyone else. Best-effort — a publish failure is logged, not
	// returned, because the periodic reconciler is the authoritative backstop.
	s.enqueueMirrorPermsBackfill(ctx, jurisdiction, clusterSlug, githubRepoID)
	return result, nil
}

// permsBackfillPublishTimeout bounds the enqueue hop. A healthy JetStream acks
// in single-digit ms; this is the ceiling we're willing to add to a mirror
// create for the backfill enqueue before giving up and leaning on the periodic
// reconciler. It is deliberately far below the gateway's request deadline so a
// stuck publish degrades to a logged warning instead of a 504.
const permsBackfillPublishTimeout = 2 * time.Second

// enqueueMirrorPermsBackfill publishes the collaborator-reconcile job for a
// freshly-created placement. A nil publisher (dev without NATS) or a publish
// error degrades to the periodic reconciler — logged, never returned, so mirror
// create never fails on the backfill hop.
//
// The publish waits for the JetStream ack (a rejected or dropped enqueue is
// loud, not silently lost) but on a short budget — permsBackfillPublishTimeout,
// or whatever is left of the request deadline when that is sooner. A JetStream
// publish that never acks — a NATS publish permissions gap, a sick stream —
// otherwise blocks to the gateway deadline and 504s a create whose placement
// already exists. Deriving pubCtx FROM ctx (not detaching it) means a healthy
// publish still acks in ms, a stuck one gives up at the cap, and the enqueue
// never runs the request past its own deadline.
func (s *Server) enqueueMirrorPermsBackfill(ctx context.Context, jurisdiction, clusterSlug string, githubRepoID int64) {
	if s.mirrorPermsBackfill == nil {
		return
	}
	pubCtx, cancel := context.WithTimeout(ctx, permsBackfillPublishTimeout)
	defer cancel()
	if err := s.mirrorPermsBackfill.PublishBackfill(pubCtx, jurisdiction, clusterSlug, githubRepoID); err != nil {
		slogutil.Warn(ctx, "mirrorperms: enqueue backfill on create failed (periodic reconciler will backfill)",
			slog.Int64("github_repo_id", githubRepoID),
			slog.String("cluster", clusterSlug),
			slog.Any("error", err))
	}
}

// recordMirrorCreatorGrant records the creator's mirror grant bookkeeping row
// (repo_permissions) at role ("writer" = pull+push, "reader" = pull-only). The
// role mirrors the access the caller holds on the GitHub upstream, so a
// read-only collaborator who mirrors a repo can't gain push on the mirror. A
// writer grant is read+write: the schema resolves pull from push and push from
// writer. Idempotent via the upsert.
//
// The ENFORCEMENT half — the SpiceDB grant the STS mirror gate
// (checkMirrorAccess → SpiceDB repo#pull / repo#push) reads — is written by
// RegisterMirrorAsNativeRepo in the same WriteRelationships as the repo's
// structural edges (SeedGrant), so this row is listing metadata, not the thing
// keeping the creator from being locked out.
func (s *Server) recordMirrorCreatorGrant(ctx context.Context, accountID model.AccountID, mirrorID, role string) *MirrorOpError {
	if s.resource == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "resource service not configured"}
	}
	repoID, err := model.ParseRepoID(mirrorID)
	if err != nil {
		slogutil.Error(ctx, "mirror create: parse mirror id for creator grant", slog.String("mirror_repo_id", mirrorID), slog.Any("error", err))
		return &MirrorOpError{Status: http.StatusInternalServerError, Message: "record creator access: invalid mirror id"}
	}
	if err := s.resource.RecordRepoAccess(ctx, repoID, "account", model.ID(accountID.String()), role); err != nil {
		slogutil.Error(ctx, "mirror create: record creator grant failed",
			slog.String("mirror_repo_id", mirrorID),
			slog.String("account_id", accountID.String()),
			slog.String("role", role),
			slog.String("error", err.Error()))
		return &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("record creator access: %v", err)}
	}
	return nil
}

// AdminCreateMirrorPlacement is the platform-admin variant of
// CreateMirrorPlacement: it drops the caller-access gate the user path
// enforces (authorizeUserMirrorCreate), so an operator can mirror a repo
// they don't collaborate on. Both paths use EnsureRepoKnown to establish the
// installation + repo rows; the App must still be installed upstream. No
// per-collaborator access is recorded — mirror authz lives in SpiceDB, and
// the operator path seeds no human grant (the operator isn't the owner).
//
// Authorization is enforced by the only caller, the platform-admin-gated
// POST /api/admin/mirrors handler.
func (s *Server) AdminCreateMirrorPlacement(ctx context.Context, provider, owner, repo, clusterHost string) (*CreateMirrorResult, error) {
	if s.mirrorRepos == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror service not configured"}
	}
	if s.repoBridge == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "data plane bridge not configured"}
	}
	if s.githubPerms == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "github perms service not configured"}
	}
	if s.ghAppCaps == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror bootstrapper not configured"}
	}

	req := mirrorOpRequest{Provider: provider, Owner: owner, Repo: repo, ClusterHost: clusterHost}
	owner, repo, status, err := req.validate()
	if err != nil {
		return nil, &MirrorOpError{Status: status, Message: err.Error()}
	}

	clusterSlug, jurisdiction, publicURL, status, err := s.resolveClusterHost(ctx, clusterHost)
	if err != nil {
		return nil, &MirrorOpError{Status: status, Message: err.Error()}
	}
	if oe := s.jurisdictionRedirect(jurisdiction); oe != nil {
		return nil, oe
	}

	// Establish the repo row from the App's token in place of the caller
	// bootstrap + CanPull gate. App-installed is still required.
	githubRepoID, isPrivate, err := s.ghAppCaps.Bootstrapper.EnsureRepoKnown(ctx, owner, repo, time.Now())
	if err != nil {
		// Operator path: no caller gate to conflate, so keep the honest surface.
		return nil, s.mapBootstrapError(ctx, owner, repo, err, false)
	}

	// Resolve the parent mirrors-project owner. No caller gate (operator
	// authority), but the anchor must exist: an unlinked org or an owner with
	// no Entire account strands the create.
	projectOwner, oerr := s.resolveAdminMirrorOwner(ctx, owner)
	if oerr != nil {
		return nil, oerr
	}

	// nil seed: the operator path implies no human grant (see CreateMirror).
	return s.finishMirrorPlacement(ctx, owner, repo, clusterHost, clusterSlug, jurisdiction, publicURL, githubRepoID, isPrivate, projectOwner, nil)
}

// mapBootstrapError translates an EnsureRepoKnown failure into a
// MirrorOpError. The "app not installed" text is honest here — the admin
// path has no collaborator check to conflate it with.
func (s *Server) mapBootstrapError(ctx context.Context, owner, repo string, err error, hideExistence bool) *MirrorOpError {
	switch {
	case errors.Is(err, permssnapshotter.ErrAppNotInstalled):
		// EnsureRepoKnown folds "repo missing / not visible" into
		// ErrAppNotInstalled (its "repo gone post-lookup" branch), so on the
		// user create path this also covers a repo that does not exist. Collapse
		// it into the existence-agnostic denial so it can't be told apart from a
		// caller-lacks-read denial (ENT-1021); the admin path keeps the honest
		// install hint.
		if hideExistence {
			return s.errMirrorRepoInaccessible()
		}
		slogutil.Info(ctx, "admin mirror create: app not installed",
			slog.String("owner", owner), slog.String("repo", repo), slog.String("error", err.Error()))
		return &MirrorOpError{Status: http.StatusNotFound, Message: s.errAppNotInstalled()}
	case errors.Is(err, permssnapshotter.ErrInstallationUnhealthy):
		slogutil.Error(ctx, "admin mirror create: installation unhealthy (403)",
			slog.String("owner", owner), slog.String("repo", repo), slog.String("error", err.Error()))
		return &MirrorOpError{Status: http.StatusBadGateway, Message: "github app installation appears unhealthy (suspended, key revoked, or sso-blocked); contact your operator"}
	default:
		slogutil.Error(ctx, "admin mirror create: bootstrap failed",
			slog.String("owner", owner), slog.String("repo", repo), slog.String("error", err.Error()))
		return &MirrorOpError{Status: http.StatusBadGateway, Message: fmt.Sprintf("ensure repo known: %v", err)}
	}
}

// publishMirrorCreated fires the mirror.created lifecycle event that drives the
// COR-717 GitHub-metadata seed. It lives in the shared create tail (called from
// finishMirrorPlacement) rather than the v1 huma handler so BOTH the user path
// (CreateMirrorPlacement) and the admin path (AdminCreateMirrorPlacement) emit
// it — before this, admin-mirrored repos synced git content but never got a
// github_repo_meta row, blanking their session view (COR-779). Only on a fresh
// placement: the create is idempotent, so a repeat (created == false) must not
// look like a new resource. The actor is the acting account from the request
// context (empty when unauthenticated — the event is metadata, not authz).
// Best-effort and nil-safe via Emitter.Publish.
func (s *Server) publishMirrorCreated(ctx context.Context, mirrorID string, created bool) {
	if !created {
		return
	}
	var actor string
	if claims := ClaimsFromContext(ctx); claims != nil {
		actor = claims.AccountID.String()
	}
	s.LifecycleEvents().Publish(ctx, resourceevents.TypeMirror, mirrorID, resourceevents.OpCreated, actor)
}

// seedMirrorVisibility seeds SpiceDB visibility on a fresh mirror placement so a
// newly-mirrored public repo is immediately visible rather than private until the
// first reconcile or webhook (COR-758). isPrivate comes from the GitHub object
// EnsureRepoKnown fetched earlier in this request — not a DB read: re-reading
// the row that same call just wrote could never be a follower read, so from a
// non-primary region it was a guaranteed cross-region hop for a value already
// in hand. Best-effort: any failure is logged and swallowed — the reconcile
// pass heals it.
func (s *Server) seedMirrorVisibility(ctx context.Context, githubRepoID int64, mirrorID model.RepoID, isPrivate bool) {
	if s.mirrorRepos == nil || s.authz == nil {
		return
	}
	seedMirrorVisibilityWith(ctx, githubRepoID, mirrorID, s.mirrorRepos, s.authz, isPrivate)
}

// seedMirrorVisibilityWith is the testable core of seedMirrorVisibility: it takes
// the two mirrorvis interfaces directly so unit tests can inject fakes without a
// real DB or SpiceDB.
func seedMirrorVisibilityWith(ctx context.Context, githubRepoID int64, mirrorID model.RepoID, placements mirrorvis.PlacementLister, vis mirrorvis.PublicAccessStore, isPrivate bool) {
	if placements == nil || vis == nil {
		return
	}
	if err := mirrorvis.PropagateMirrorVisibility(ctx, placements, vis, githubRepoID, isPrivate); err != nil {
		slogutil.Warn(ctx, "mirror create: visibility seed failed (best-effort)",
			slog.Int64("github_repo_id", githubRepoID),
			slog.String("mirror_repo_id", mirrorID.String()),
			slog.String("error", err.Error()))
	}
}

// provisionMirrorsProject lazily creates (or finds) the per-cluster mirrors
// project for the resolved owner, retrying once when the owner org vanished
// under us: the mirror-teardown reap (reapEmptyLinkedOrg) can delete a
// linked org between the owner resolution — a follower read, up to ~4.8s
// stale — and the project insert. CreateOrFindMirrorsProject detects that
// in-transaction (resource.ErrOwnerGone; projects carry no owner FK) and
// the retry re-mints the linked org FRESH (a follower find would keep
// returning the deleted org for the staleness window), then re-attempts
// the project once. The re-minted org cannot itself be reaped in the
// window — the reap only fires off a project delete under the org, and the
// new org owns nothing yet — so one retry converges.
//
// The GitHubOrgID guard is the one leg the re-mint needs: account owners
// never see ErrOwnerGone (teardown never reaps accounts) and carry zero
// coords, so they fall through to the generic failure.
func (s *Server) provisionMirrorsProject(ctx context.Context, projectOwner mirrorProjectOwner, clusterSlug, jurisdiction string) (*model.Project, *MirrorOpError) {
	project, _, err := s.resource.CreateOrFindMirrorsProject(ctx, projectOwner.Type, projectOwner.ID, clusterSlug, jurisdiction)
	if errors.Is(err, resource.ErrOwnerGone) && projectOwner.GitHubOrgID > 0 {
		slogutil.Info(ctx, "mirror create: linked org reaped mid-create; re-minting fresh and retrying",
			slog.String("reaped_org_id", projectOwner.ID.String()),
			slog.Int64("github_org_id", projectOwner.GitHubOrgID),
			slog.String("cluster_slug", clusterSlug))
		org, _, mintErr := s.resource.CreateOrFindGitHubLinkedOrgFresh(ctx, projectOwner.GitHubOrgID, projectOwner.GitHubOrgLogin, s.jurisdiction)
		if mintErr != nil {
			slogutil.Error(ctx, "mirror create: re-mint linked org failed",
				slog.Int64("github_org_id", projectOwner.GitHubOrgID),
				slog.Any("error", mintErr))
			return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("re-mint linked org: %v", mintErr)}
		}
		projectOwner.ID = model.ID(org.ID.String())
		project, _, err = s.resource.CreateOrFindMirrorsProject(ctx, projectOwner.Type, projectOwner.ID, clusterSlug, jurisdiction)
	}
	if err != nil {
		slogutil.Error(ctx, "mirror create: provision mirrors project failed",
			slog.String("owner_type", projectOwner.Type),
			slog.String("owner_id", projectOwner.ID.String()),
			slog.String("cluster_slug", clusterSlug),
			slog.Any("error", err))
		return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("provision mirrors project: %v", err)}
	}
	return project, nil
}

// finishMirrorPlacement is the shared tail of CreateMirrorPlacement and
// AdminCreateMirrorPlacement: resolve installation_id, create the
// mirror_repos row, provision it, publish the initial sync, and kick the
// async collaborator backfill. Both entry points reach here once the
// github_repos row exists; they differ only in the access gate before it.
//
// creatorSeed is the human creator's grant on the user path, nil on the
// operator/admin path; it is folded into RegisterMirrorAsNativeRepo's single
// SpiceDB write below. The sync pipeline itself needs no grant: mirror-worker
// authenticates to entire-server cert-only (docs/auth.md §3.2).
func (s *Server) finishMirrorPlacement(ctx context.Context, owner, repo, clusterHost, clusterSlug, jurisdiction, publicURL string, githubRepoID int64, isPrivate bool, projectOwner mirrorProjectOwner, creatorSeed *regional.SeedGrant) (*CreateMirrorResult, error) {
	// Resolve installation_id BEFORE writing any mirror metadata. The
	// perms DB is the source of truth for installation_id; without a
	// non-zero value we can't stamp the entire-server `repos` row at
	// Provision time, which would strand the placement behind a
	// permanent 412 from resolveMirrorPushTarget on every push. Doing
	// the check up-front means a "webhook not yet observed" 412 leaves
	// no rows behind — no mirror_repos row, no URL row, no SpiceDB
	// grant — so the operator can simply retry once the webhook lands
	// without an orphan to clean up first.
	//
	// This read stays FRESH (no COR-371 follower read): EnsureRepoKnown
	// just stamped installation_id on this same github_repos row moments
	// ago, so a follower read (~4.8s stale) would return the pre-write
	// value — a stale NULL or a superseded installation — and spuriously
	// 412 (or stamp the wrong installation onto the data-plane repos row).
	notObserved := "GitHub App install for " + owner + "/" + repo + " not yet observed. Confirm the App is installed on the upstream and retry in a few seconds."
	installationID, err := s.githubPerms.LookupInstallationIDForRepo(ctx, githubRepoID)
	switch {
	case errors.Is(err, githubperms.ErrRepoNotKnown):
		// Race: the github_repos row vanished between the earlier
		// LookupRepoIDByCoords and this call (App uninstalled, or
		// repo deleted upstream). Same retry posture as the
		// "webhook not yet observed" case below.
		return nil, &MirrorOpError{Status: http.StatusPreconditionFailed, Message: notObserved}
	case err != nil:
		slogutil.Error(ctx, "mirror create: lookup installation id failed", slog.Any("error", err))
		return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("lookup installation id: %v", err)}
	case installationID == 0:
		return nil, &MirrorOpError{Status: http.StatusPreconditionFailed, Message: notObserved}
	}

	// Lazily provision the per-cluster mirrors project that parents this mirror
	// (COR-433), now that we know the placement is viable. Fatal on error so
	// every placed mirror's cell has its project. Idempotent: re-creates find
	// the existing project. The mirror is attached to it as a native repo
	// below (RegisterMirrorAsNativeRepo, COR-434).
	//
	// resource and regional are only ever wired together (JurisdictionCapabilities
	// is all-or-nothing), so the two former separate checks collapse to one —
	// see NewJurisdictionCapabilities and the mode switch in buildAPIConfig.
	if s.jurCaps == nil {
		return nil, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "resource service not configured"}
	}
	mirrorsProject, oe := s.provisionMirrorsProject(ctx, projectOwner, clusterSlug, jurisdiction)
	if oe != nil {
		return nil, oe
	}

	url := mirrorrepo.MirrorURL(owner, repo)
	mirror, created, err := s.mirrorRepos.Create(ctx, githubRepoID, clusterSlug, url)
	if err != nil {
		if errors.Is(err, mirrorrepo.ErrURLConflict) {
			return nil, &MirrorOpError{Status: http.StatusConflict, Message: "mirror URL already in use"}
		}
		slogutil.Error(ctx, "mirror create: create mirror failed", slog.Any("error", err))
		return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("create mirror: %v", err)}
	}

	// Stamp the upstream URL + installation id on the entire-server
	// `repos` row at provision time so server/githttp's isMirrorRepo /
	// resolveMirrorPushTarget branch engages on user pushes — both for
	// the canonical /gh/<owner>/<repo> URL and for any operator-INSERTed
	// /git/* alias pointing at the same ULID (the operator escape
	// hatch). Synthesising upstream from the
	// request path would only cover /gh/* and would break the alias case.
	upstreamURL := mirrorrepo.UpstreamURL(owner, repo)

	// Resolve the placement-independent group ULID for this upstream so every
	// cell's mirror of the same GitHub repo shares one origin identity. Sent
	// to the data plane below and stamped onto ref events there, so downstream
	// activity dedup keys on the origin rather than this placement's ULID.
	repoGroupID, err := s.jurCaps.Resource.GetOrCreateRepoGroup(ctx, resource.ForgeGitHub, githubRepoID)
	if err != nil {
		slogutil.Error(ctx, "mirror create: resolve repo group failed",
			slog.Int64("github_repo_id", githubRepoID),
			slog.Any("error", err))
		return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("resolve repo group: %v", err)}
	}

	// Tell entire-server about the URL → ULID mapping. ObjectFormat is
	// hardcoded to "sha1" because GitHub repositories are sha1-only —
	// the SHA-256 transition is still experimental on GitHub's side and
	// no mirrored upstream can be sha256 today. Revisit when GitHub
	// flips that on; until then a literal is more honest than a
	// per-repo plumb-through that would never carry a different value.
	if err := s.repoBridge.Provision(ctx, mirror.ID, clusterSlug, url, upstreamURL, installationID, "sha1", repoGroupID.String()); err != nil {
		// Best-effort rollback: the mirror_repos row is now orphaned
		// without a data-plane provisioning. The reconciler is
		// expected to drive the data-plane provisioning on its next
		// pass; we don't unwind here because deleting after a
		// half-applied state stranded the SpiceDB grant would be
		// worse than the orphan.
		slogutil.Error(ctx, "mirror create: data-plane provision failed",
			slog.String("mirror_repo_id", mirror.ID.String()),
			slog.String("cluster_slug", clusterSlug),
			slog.String("error", err.Error()))
		return nil, &MirrorOpError{Status: http.StatusBadGateway, Message: fmt.Sprintf("provision mirror on data plane: %v", err)}
	}

	// Register the placed mirror as a native repo under its mirrors project:
	// regional repos row + global repo_registry row + SpiceDB repo#project
	// edge, reusing the mirror ULID so the data plane's /gh/ resolution (by
	// ULID) is untouched. Idempotent — a retried create re-asserts the edge
	// and registry row, so a registration that died mid-way self-heals.
	//
	// Fold the up-front SpiceDB grant into this one write: the creator's
	// grant on the user path. Batching it with the structural edges is one
	// round trip to the primary-region authz-writer instead of one per grant
	// — the mirror-create latency win a far-from-writer region cares about.
	// The sync pipeline needs no grant here: mirror-worker is an internal
	// workload authorized cert-only from entire-server's inbound write-mirror
	// allowlist (docs/auth.md §3.2), not a SpiceDB account.
	var seeds []regional.SeedGrant
	if creatorSeed != nil {
		seeds = append(seeds, *creatorSeed)
	}
	if _, err := s.jurCaps.Regional.RegisterMirrorAsNativeRepo(ctx, mirror.ID, mirrorsProject, repo, clusterSlug, seeds); err != nil {
		if errors.Is(err, regional.ErrNameConflict) {
			return nil, &MirrorOpError{Status: http.StatusConflict, Message: "a repo with that name already exists in the mirrors project"}
		}
		slogutil.Error(ctx, "mirror create: promote to native repo failed",
			slog.String("mirror_repo_id", mirror.ID.String()),
			slog.String("project_id", mirrorsProject.ID.String()),
			slog.String("error", err.Error()))
		return nil, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("promote mirror to native repo: %v", err)}
	}

	// Publish mirror.git.v1.<jur>.<cluster>.github.sync_repo so the
	// per-cluster mirror-worker picks up the initial clone right
	// now, instead of waiting for the periodic resync window. We
	// surface a publish failure to the caller (502) rather than
	// returning 2xx — otherwise --wait blocks forever on a placement
	// that was never queued, and the silent "resync will retry"
	// posture cost us a day of debugging EU mirrors that had no
	// resync scheduler in their region. Retry is safe: Create and
	// Provision are idempotent on (github_repo_id, cluster_slug),
	// and PublishSyncRepo dedups within StreamDuplicatesWindow via
	// Nats-Msg-Id.
	if err := s.publishMirrorSync(ctx, jurisdiction, clusterSlug, owner, repo, installationID, mirror.ID.String()); err != nil {
		slogutil.Error(ctx, "mirror create: sync_repo publish failed",
			slog.String("mirror_repo_id", mirror.ID.String()),
			slog.String("cluster_slug", clusterSlug),
			slog.String("jurisdiction", jurisdiction),
			slog.String("error", err.Error()))
		return nil, &MirrorOpError{Status: http.StatusBadGateway, Message: fmt.Sprintf("publish initial sync_repo: %v", err)}
	}

	// Seed GitHub display metadata (COR-717) on a fresh placement, from the
	// shared tail so user and admin creates can't drift (COR-779).
	s.publishMirrorCreated(ctx, mirror.ID.String(), created)

	// Seed SpiceDB visibility so a freshly-mirrored public repo is immediately
	// public rather than private until the first reconcile/webhook (COR-758).
	// Best-effort — a failure here doesn't fail the create; the reconcile heals it.
	s.seedMirrorVisibility(ctx, githubRepoID, mirror.ID, isPrivate)

	// Created drives the 201-vs-200 status the caller returns. The CLI
	// uses it to pick the trace-style verb ("registered new mirror" vs
	// "found existing mirror"), keeping the wire shape trivially scriptable.
	return &CreateMirrorResult{
		MirrorID:  mirror.ID.String(),
		MirrorURL: "entire://" + clusterHost + url,
		PublicURL: publicURL + url,
		Created:   created,
		Suspended: mirror.SuspendedAt != nil,
	}, nil
}

// publishMirrorSync fires the canonical sync_repo job. Pulled out so
// the create handler reads linearly; failure is now fatal to the
// request (caller returns 502).
//
// installation_id is resolved by the caller and threaded through —
// the same value is persisted on the entire-server repos row so
// push-through and the worker resync agree on which App identity
// authorises upstream operations. The caller guarantees a non-zero
// installation_id (CreateMirrorPlacement 412s otherwise), so auth_ref
// is always populated.
//
// s.gitJobsPub is required at construction time
// (buildGitJobsPublisher errors if ENTIRE_NATS_URL is unset), so we
// don't nil-check here — a nil publisher would be a programmer
// error and the panic is the desired signal.
func (s *Server) publishMirrorSync(ctx context.Context, jurisdiction, clusterSlug, owner, repo string, installationID int64, mirrorULID string) error {
	if err := s.gitJobsPub.PublishSyncRepo(ctx,
		gitjobs.Placement{Jurisdiction: jurisdiction, ClusterID: clusterSlug},
		gitjobs.Source{
			Owner:   owner,
			Repo:    repo,
			AuthRef: gitjobs.FormatGithubInstallationAuthRef(installationID),
		},
		gitjobs.Target{ULID: mirrorULID},
	); err != nil {
		return fmt.Errorf("publish sync_repo: %w", err)
	}
	return nil
}

// DeleteMirrorPlacement tears down the mirror placement for (owner, repo)
// on the cluster behind clusterHost. It is the single source of truth for
// mirror deletion; coreapi's DELETE /api/v1/mirrors/{id} resolves the ULID
// to its coords and calls this. Returns nil on success (the caller sends
// 204) or a *MirrorOpError.
//
// Removal requires a LIVE GitHub repo-admin verdict on the upstream
// (authorizeMirrorManage): a repo-admin for an org-owned upstream, or the owner
// of a user-owned one. Stricter than create's read gate — tearing down a mirror
// is destructive, so a read-only collaborator who can spin one up may not
// remove it. Step order matters: storage delete on entire-server FIRST so a
// transient storage failure doesn't strand the metadata in a "removed but
// storage lives" state.
func (s *Server) DeleteMirrorPlacement(ctx context.Context, claims *authn.Claims, provider, owner, repo, clusterHost string) error {
	if claims == nil {
		return &MirrorOpError{Status: http.StatusUnauthorized, Message: "unauthenticated"}
	}
	if s.mirrorRepos == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror service not configured"}
	}
	if s.repoBridge == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "data plane bridge not configured"}
	}

	req := mirrorOpRequest{Provider: provider, Owner: owner, Repo: repo, ClusterHost: clusterHost}
	owner, repo, status, err := req.validate()
	if err != nil {
		return &MirrorOpError{Status: status, Message: err.Error()}
	}

	clusterSlug, jurisdiction, _, status, err := s.resolveClusterHost(ctx, clusterHost)
	if err != nil {
		return &MirrorOpError{Status: status, Message: err.Error()}
	}
	if oe := s.jurisdictionRedirect(jurisdiction); oe != nil {
		return oe
	}

	githubUserID, status, err := s.requireGitHubUser(ctx, claims)
	if err != nil {
		return &MirrorOpError{Status: status, Message: err.Error()}
	}

	// Live GitHub repo-admin gate: only an admin may un-mirror (stricter than
	// create's read gate — tearing down is destructive). Replaces the old
	// read-of-persisted-perms CanPush check. hideExistence=false: the caller
	// acts on an already-known mirror, so an informative 403 leaks nothing new.
	if _, _, oe := s.authorizeMirrorManage(ctx, claims, githubUserID, owner, repo, githubperms.PermissionAdmin, false); oe != nil {
		return oe
	}

	githubRepoID, status, err := s.lookupGitHubRepoID(ctx, owner, repo)
	if err != nil {
		return &MirrorOpError{Status: status, Message: err.Error()}
	}

	mr, err := s.mirrorRepos.GetByCoords(ctx, githubRepoID, clusterSlug)
	if err != nil {
		if errors.Is(err, mirrorrepo.ErrNotFound) {
			return &MirrorOpError{Status: http.StatusNotFound, Message: "mirror not found on this cluster"}
		}
		slogutil.Error(ctx, "mirror delete: lookup mirror failed", slog.Any("error", err))
		return &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("lookup mirror: %v", err)}
	}

	projectID, oe := s.teardownMirrorPlacement(ctx, mr.ID, clusterSlug)
	if oe != nil {
		return oe
	}
	// Reap the now-emptied parent, same best-effort semantics as the
	// webhook-driven consumer path (TeardownMirror): the reap is empty-only
	// (DeleteProject refuses a non-empty project), so a sibling placement keeps
	// the project alive and only the LAST mirror cascades to the gh: container
	// org. The synthetic gh:mirrors: project and gh: org follow reference
	// counting, not the user's per-mirror delete intent (COR-518).
	s.reapEmptyMirrorsProject(ctx, projectID)
	return nil
}

// TeardownMirror unwinds one mirror placement end to end and best-effort
// reaps the now-empty parent (the mirrors project, then its gh: container
// org). It is the entry point the repo-ops teardown consumer (repoops.Consumer)
// calls when entire-core-global fans a permanent upstream repository.deleted
// out to the region that owns the placement.
//
// The user-facing DELETE handler (DeleteMirrorPlacement) runs the same
// teardownMirrorPlacement + reapEmptyMirrorsProject pair; it differs only in
// mapping the richer *MirrorOpError to an HTTP status. Both paths reap
// identically — the reap is empty-only (DeleteProject refuses a non-empty
// project with ErrHasRepos), so a sibling placement keeps the project alive on
// either path and only the LAST mirror cascades. The gh:mirrors: project and
// gh: org are synthetic, user-invisible containers that CreateOrFind* re-mints
// on demand, so they follow reference counting, not a per-mirror delete intent.
//
// Every step is idempotent, so the consumer's redelivery-on-error
// converges: a half-finished teardown re-runs cleanly.
func (s *Server) TeardownMirror(ctx context.Context, mirrorID model.RepoID, clusterSlug string) error {
	projectID, oe := s.teardownMirrorPlacement(ctx, mirrorID, clusterSlug)
	if oe != nil {
		return oe
	}
	s.reapEmptyMirrorsProject(ctx, projectID)
	return nil
}

// reapEmptyMirrorsProject best-effort deletes the per-(owner, cluster)
// mirrors project once its last placement is gone. DeleteProject refuses a
// non-empty project (ErrHasRepos) — that's exactly the "another placement
// still lives here" case, swallowed silently — so this only ever removes a
// truly empty project, which CreateOrFindMirrorsProject lazily re-mints on
// the next mirror create. Never fails the teardown: the placement is
// already gone; a lingering empty project is reapable, not corrupting.
//
// When the reaped project was the last one under a synthetic GitHub-linked
// container org, that org is reaped too (reapEmptyLinkedOrg).
func (s *Server) reapEmptyMirrorsProject(ctx context.Context, projectID model.ProjectID) {
	var zero model.ProjectID
	if s.resource == nil || projectID == zero {
		return
	}
	deleted, err := s.resource.DeleteProject(ctx, projectID)
	if err != nil {
		if errors.Is(err, resource.ErrHasRepos) || errors.Is(err, resource.ErrNotFound) {
			return
		}
		slogutil.Warn(ctx, "mirror teardown: best-effort mirrors-project reap failed",
			slog.String("project_id", projectID.String()), slog.Any("error", err))
		return
	}
	s.reapEmptyLinkedOrg(ctx, deleted)
}

// reapEmptyLinkedOrg best-effort deletes the synthetic GitHub-linked
// container org once its last mirrors project has been reaped (COR-454).
// It only ever touches an org that:
//
//   - owns the just-reaped mirrors project (org-owned, not account-owned —
//     a user install's mirrors project hangs off the account, which is the
//     user's identity and must never be deleted here); and
//   - is a github-linked synthetic org (gh:<github_org_id>, minted with no
//     human owner/members purely to hold the mirrors project) — never a
//     real user-facing org; and
//   - has no projects left — enforced atomically by DeleteOrg itself
//     (ErrHasDependents), not a separate, racy pre-check.
//
// Cross-region "last one out" is safe, and so is a mirror-create that races
// the reap — by a two-sided guard: DeleteOrg counts owned projects inside
// its own transaction, and insertProjectRow reads the owner org row inside
// ITS transaction (retrying serialization conflicts). Whichever commits
// first is observed by the other: a project that lands before the reap
// makes DeleteOrg refuse (ErrHasDependents); a reap that lands first makes
// the insert fail (ErrOwnerGone) and the create re-mints a fresh org
// (provisionMirrorsProject). The project FIND is fresh for the same reason
// (a follower read could resurrect a just-reaped project). A sibling
// teardown that already reaped the org loses with ErrNotFound. All benign —
// skip.
//
// Never fails the teardown: an empty linked org is reapable, not
// corrupting, and CreateOrFindGitHubLinkedOrg lazily re-mints it on the
// next mirror create.
func (s *Server) reapEmptyLinkedOrg(ctx context.Context, project *model.Project) {
	if project == nil || project.OwnerType != "org" {
		return
	}
	orgID, err := model.ParseOrgID(project.OwnerID.String())
	if err != nil {
		slogutil.Warn(ctx, "mirror teardown: parse mirrors-project owner org id",
			slog.String("owner_id", project.OwnerID.String()), slog.Any("error", err))
		return
	}
	linked, err := s.resource.IsGitHubLinkedOrg(ctx, orgID)
	if err != nil {
		slogutil.Warn(ctx, "mirror teardown: github-linked org lookup failed",
			slog.String("org_id", orgID.String()), slog.Any("error", err))
		return
	}
	if !linked {
		return // a real user-facing org — never reaped by an upstream removal
	}
	// DeleteOrg refuses (ErrHasDependents) in its own transaction when the org
	// still owns any project, so we do NOT pre-check the project list: a plain
	// check would race a mirror-create that lands a new mirrors project between
	// the check and the delete, orphaning it under a deleted org.
	// ErrHasDependents means another cluster's mirrors project still lives (not
	// the last one out); ErrNotFound means a racing teardown already reaped the
	// org. Both are benign — skip.
	if err := s.resource.DeleteOrg(ctx, orgID); err != nil {
		if errors.Is(err, resource.ErrNotFound) || errors.Is(err, resource.ErrHasDependents) {
			return
		}
		slogutil.Warn(ctx, "mirror teardown: best-effort linked-org reap failed",
			slog.String("org_id", orgID.String()), slog.Any("error", err))
	}
}

// teardownMirrorPlacement is the symmetric counterpart to
// finishMirrorPlacement: it unwinds a placement in the reverse order it was
// built, and every step tolerates "already gone" so a retried delete
// converges (the mirror image of the idempotent create).
//
// Storage is deleted FIRST and the metadata facets after, holding the
// load-bearing invariant that storage must never outlive its metadata: a
// transient data-plane failure must not strand a "metadata gone, storage
// lives" repo. Do not reorder regional.DeleteRepo ahead of repoBridge.Delete.
//
// Returns the placement's owning (mirrors) project id when the native-repo
// row was present, so the caller can best-effort reap a now-empty project;
// the zero ProjectID when the mirror was never promoted (no regional row).
func (s *Server) teardownMirrorPlacement(ctx context.Context, mirrorID model.RepoID, clusterSlug string) (model.ProjectID, *MirrorOpError) {
	var owningProject model.ProjectID
	// 1. Storage + data-plane repo_urls. ErrNotFound is the success-on-retry
	//    case (a prior attempt cleared storage but not metadata).
	if err := s.repoBridge.Delete(ctx, mirrorID, clusterSlug); err != nil && !errors.Is(err, repoadmin.ErrNotFound) {
		slogutil.Error(ctx, "mirror delete: storage delete failed", slog.Any("error", err))
		return owningProject, &MirrorOpError{Status: http.StatusBadGateway, Message: fmt.Sprintf("delete mirror storage: %v", err)}
	}

	// 2. Native-repo facet: unpublish the global registry row, drop the
	//    regional row, and clear every repo#… SpiceDB relation (project edge,
	//    platform pointer, AND any creator/collaborator grants) via RepoDeleted.
	// s.regional mirrors jurCaps.Regional (see the jurCaps field doc in
	// server.go); checking it directly here is a deliberate soft-degrade kept
	// on the flat field rather than jurCaps, so partial test fixtures that
	// construct only s.regional without a full jurCaps group keep behaving
	// exactly as before this group existed. Do not mechanically fold this
	// into a jurCaps gate.
	if s.regional != nil {
		deleted, err := s.regional.DeleteRepo(ctx, mirrorID)
		switch {
		case err == nil:
			// Promoted: DeleteRepo already cleared every repo#… tuple via
			// authz.RepoDeleted. Capture the project for the empty-project reap.
			if deleted != nil {
				owningProject = deleted.OwningProjectID
			}
		case errors.Is(err, regional.ErrNotFound):
			// Never promoted (or a prior delete already dropped the native
			// repo): there is no regional row, so DeleteRepo short-circuits
			// before RepoDeleted runs. Clear any repo#… tuples explicitly here
			// (e.g. a creator seed from a half-applied create, or a legacy
			// mirror-worker writer grant from before the cert-only cutover) —
			// otherwise teardown leaves them orphaned in SpiceDB.
			// Swallow-and-log like regional.DeleteRepo: the DB rows are the
			// source of truth and a stray tuple for a deleted repo is reapable.
			if s.authz != nil {
				if aerr := s.authz.RepoDeleted(ctx, mirrorID); aerr != nil {
					slogutil.Error(ctx, "mirror delete: authz cleanup for unpromoted mirror failed",
						slog.String("mirror_repo_id", mirrorID.String()), slog.Any("error", aerr))
				}
			}
		default:
			slogutil.Error(ctx, "mirror delete: native repo delete failed", slog.Any("error", err))
			return owningProject, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("delete native repo: %v", err)}
		}
	}

	// 3. Mirror placement tables (github_mirror_repo_urls cascades off the FK).
	if err := s.mirrorRepos.Delete(ctx, mirrorID); err != nil && !errors.Is(err, mirrorrepo.ErrNotFound) {
		slogutil.Error(ctx, "mirror delete: metadata delete failed", slog.Any("error", err))
		return owningProject, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("delete mirror metadata: %v", err)}
	}
	return owningProject, nil
}

package coreapi

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/core/model"
	"entire.io/core/pagination"
	"entire.io/core/repodirectory"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

// MirrorService backs /api/v1/mirrors. The handlers are thin huma
// adapters: List/Get read via api.Server accessors, while Create/Delete
// orchestrate through api.Server.CreateMirrorPlacement /
// DeleteMirrorPlacement (the cross-jurisdiction redirect, GitHub-perms,
// and NATS-publish flows live there, where their dependencies are wired).
type MirrorService struct {
	Server *api.Server
}

// ListMirrors returns the mirrors the calling account is affiliated with.
// Mirrors are native repos (COR-434) with per-user SpiceDB grants, so the
// visible set is the repo#list reverse lookup hydrated to rows, across all
// jurisdictions — both reader and writer grants surface; unaffiliated public
// mirrors don't (see ListableMirrorRows for why list, not pull). Filters
// (cluster, provider, owner) are applied client-side after the visibility
// scan so a missing provider filter still scopes to GitHub. The optional
// cluster filter is just a filter, not a router: a single core returns
// mirrors on every cluster in the caller's list set, regardless of
// jurisdiction.
func (s *MirrorService) ListMirrors(ctx context.Context, in *corev1.ListMirrorsInput) (*corev1.ListMirrorsOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	rows, next, err := s.Server.ListableMirrorRowsPage(ctx, claims.AccountID, int(in.PageSize), in.PageToken)
	if err != nil {
		if errors.Is(err, pagination.ErrMalformedCursor) {
			return nil, badRequest("invalid pageToken")
		}
		slogutil.Error(ctx, "ListableMirrorRows failed", slog.Any("error", err))
		return nil, internalErr()
	}
	// mirrorrepo.ListAll currently returns only GitHub-backed mirrors —
	// see core/mirrorrepo's ProviderGitHub comment. Surface each row's
	// provider via a single source of truth so the filter compares
	// row.Provider == in.Provider rather than hard-coding the only
	// supported provider into the filter logic, where it would silently
	// misbehave the day a second provider is added.
	const rowProvider = "github"
	// Resolve each row's cluster slug to its public host once per slug —
	// mirror lists span few clusters, so the memo keeps this O(clusters)
	// rather than O(rows).
	hostFor := repodirectory.ClusterHostMemo(ctx, s.Server)
	out := &corev1.ListMirrorsOutput{}
	out.Body.Mirrors = make([]corev1.Mirror, 0, len(rows))
	for _, r := range rows {
		host := hostFor(r.ClusterSlug)
		if in.Cluster != "" && host != in.Cluster {
			continue
		}
		if in.Provider != "" && !strings.EqualFold(in.Provider, rowProvider) {
			continue
		}
		if in.Owner != "" && !strings.EqualFold(r.OwnerLogin, in.Owner) {
			continue
		}
		m := corev1.Mirror{
			MirrorID:     r.ID.String(),
			Provider:     "github",
			Owner:        r.OwnerLogin,
			Repo:         r.RepoName,
			ClusterHost:  host,
			Jurisdiction: r.Jurisdiction,
			Cell:         r.Cell,
			IsPrivate:    r.IsPrivate,
			IsArchived:   r.IsArchived,
			CreatedAt:    r.CreatedAt,
			SuspendedAt:  r.SuspendedAt,
			Status:       r.Status,
		}
		if r.InstallationID != nil {
			m.InstallationID = *r.InstallationID
		}
		out.Body.Mirrors = append(out.Body.Mirrors, m)
	}
	// nextCursor is the underlying (pre-filter) page boundary; with a
	// cluster/owner/provider filter active a page may hold fewer than limit
	// rows while more pages remain — the client pages until it's empty.
	out.Body.NextPageToken = next
	return out, nil
}

// ListAvailableMirrors returns the GitHub repos the caller could onboard as
// mirrors, computed live from GitHub via the caller's own user-to-server
// token (api.Server.ListAvailableMirrors). Unlike ListMirrors (which reads
// the SpiceDB list set), this is a synchronous GitHub round-trip, so its
// failure modes — no GitHub link / expired token (401) and GitHub transport
// faults (502) — flow through mapOpError. The optional owner filter is
// applied client-side, matching ListMirrors.
func (s *MirrorService) ListAvailableMirrors(ctx context.Context, in *corev1.ListAvailableMirrorsInput) (*corev1.ListAvailableMirrorsOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	rows, err := s.Server.ListAvailableMirrors(ctx, claims)
	if err != nil {
		return nil, mapOpError(err)
	}
	out := &corev1.ListAvailableMirrorsOutput{}
	out.Body.Available = make([]corev1.AvailableMirror, 0, len(rows))
	for _, r := range rows {
		if in.Owner != "" && !strings.EqualFold(r.Owner, in.Owner) {
			continue
		}
		out.Body.Available = append(out.Body.Available, corev1.AvailableMirror{
			Owner:      r.Owner,
			Repo:       r.Repo,
			IsPrivate:  r.IsPrivate,
			IsArchived: r.IsArchived,
			Access:     r.Access,
			Status:     r.Status,
		})
	}
	return out, nil
}

// GetMirror returns one mirror by ID. 404 when the caller holds no grant on
// the underlying repo, matching the listing's visibility rule and keeping
// the endpoint enumeration-safe.
func (s *MirrorService) GetMirror(ctx context.Context, in *corev1.GetMirrorInput) (*corev1.GetMirrorOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	mirrorID, err := model.ParseRepoID(in.MirrorID)
	if err != nil {
		return nil, badRequest("invalid mirror id")
	}
	// Mirror visibility is the SpiceDB repo#list reverse lookup: a mirror the
	// caller holds no grant on is absent from the rows and falls through to
	// 404 (not 403) so the endpoint isn't an enumeration oracle. This
	// deliberately diverges from GET /repos/{id}, which point-checks repo#pull
	// and so serves public repos to strangers — the mirror surface is
	// affiliation-scoped end to end, by-ID reads included.
	rows, err := s.Server.ListableMirrorRows(ctx, claims.AccountID)
	if err != nil {
		slogutil.Error(ctx, "ListableMirrorRows failed", slog.Any("error", err))
		return nil, internalErr()
	}
	for _, r := range rows {
		if r.ID != mirrorID {
			continue
		}
		host, herr := s.Server.ClusterPublicHost(ctx, r.ClusterSlug)
		if herr != nil {
			slogutil.Error(ctx, "ClusterPublicHost failed", slog.String("slug", r.ClusterSlug), slog.Any("error", herr))
		}
		m := corev1.Mirror{
			MirrorID:     r.ID.String(),
			Provider:     "github",
			Owner:        r.OwnerLogin,
			Repo:         r.RepoName,
			ClusterHost:  host,
			Jurisdiction: r.Jurisdiction,
			Cell:         r.Cell,
			IsPrivate:    r.IsPrivate,
			IsArchived:   r.IsArchived,
			CreatedAt:    r.CreatedAt,
			SuspendedAt:  r.SuspendedAt,
			Status:       r.Status,
		}
		if r.InstallationID != nil {
			m.InstallationID = *r.InstallationID
		}
		return &corev1.GetMirrorOutput{Body: m}, nil
	}
	return nil, notFound("mirror not found")
}

// CreateMirror provisions a new GitHub mirror. Body fields carry the
// upstream coords + target cluster host; the response uses the camelCase
// /api/v1 shape. The orchestration lives on api.Server; this is the huma
// adapter over it.
func (s *MirrorService) CreateMirror(ctx context.Context, in *corev1.CreateMirrorInput) (*corev1.CreateMirrorOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	res, err := s.Server.CreateMirrorPlacement(ctx, claims, in.Body.Provider, in.Body.Owner, in.Body.Repo, in.Body.ClusterHost)
	if err != nil {
		return nil, mapOpError(err)
	}
	// mirror.created is published by finishMirrorPlacement (COR-779) so the
	// admin create path emits it too — nothing to publish here.

	// Always 201, whether the placement was freshly inserted or already
	// existed (the create is idempotent). The body's Created flag is the
	// signal for which — the status need not also encode it.
	// Empty is pinned false: the live GitHub emptiness probe it used to carry
	// cost a full RTT to GitHub on every create for a cosmetic field. An empty
	// upstream still reaches status 'ready' (the worker publishes mirror_done
	// for a no-refs source), so pollers terminate normally either way. The
	// field stays on the wire because deployed CLIs require the key to decode.
	return &corev1.CreateMirrorOutput{
		Status: http.StatusCreated,
		Body: corev1.CreatedMirror{
			MirrorID:  res.MirrorID,
			MirrorURL: res.MirrorURL,
			PublicURL: res.PublicURL,
			Created:   res.Created,
			Empty:     false,
			Suspended: res.Suspended,
		},
	}, nil
}

// mirrorCoordsID is the resource id carried on mirror lifecycle events that
// are addressed by upstream coords + cluster rather than the mirror ULID
// (delete and collaborator grant/revoke). Shape: provider/owner/repo@host.
func mirrorCoordsID(provider, owner, repo, clusterHost string) string {
	return provider + "/" + owner + "/" + repo + "@" + clusterHost
}

// DeleteMirror tears down a mirror placement addressed by its upstream
// coords (provider/owner/repo) plus the targeted cluster host. The
// orchestration — cross-jurisdiction 421 redirect, the LIVE GitHub-admin
// gate, placement lookup (404 when the upstream isn't mirrored on the named
// cluster), and storage-before-metadata teardown — all live in
// DeleteMirrorPlacement; this is the thin huma adapter over it. A non-admin
// caller is rejected by that gate (403), matching create.
func (s *MirrorService) DeleteMirror(ctx context.Context, in *corev1.DeleteMirrorInput) (*corev1.DeleteMirrorOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	if err := s.Server.DeleteMirrorPlacement(ctx, claims, in.Provider, in.Owner, in.Repo, in.ClusterHost); err != nil {
		return nil, mapOpError(err)
	}
	// Addressed by upstream coords + cluster, not the mirror ULID (the
	// teardown doesn't surface it), so the event carries the same coords id.
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeMirror, mirrorCoordsID(in.Provider, in.Owner, in.Repo, in.ClusterHost), resourceevents.OpDeleted, claims.AccountID.String())
	return &corev1.DeleteMirrorOutput{Status: http.StatusNoContent}, nil
}

// ListCollaborators returns the principals with effective access to a mirror,
// with reader/writer roles. Same live GitHub-admin gate as grant/revoke. Thin
// adapter over api.Server.ListMirrorCollaborators.
//
// Not paginated (COR-583): the collaborator set is the reader/writer subjects on
// a single repo (bounded, small), and it's resolved via SpiceDB LookupSubjects,
// which does not support cursors yet (optional_cursor is ignored by SpiceDB).
func (s *MirrorService) ListCollaborators(ctx context.Context, in *corev1.ListMirrorCollaboratorsInput) (*corev1.ListMirrorCollaboratorsOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	collabs, err := s.Server.ListMirrorCollaborators(ctx, claims, in.Provider, in.Owner, in.Repo, in.ClusterHost)
	if err != nil {
		return nil, mapOpError(err)
	}
	out := &corev1.ListMirrorCollaboratorsOutput{}
	out.Body.Collaborators = make([]corev1.MirrorCollaborator, 0, len(collabs))
	for _, c := range collabs {
		out.Body.Collaborators = append(out.Body.Collaborators, corev1.MirrorCollaborator{
			AccountID: c.AccountID,
			Handle:    c.Handle,
			Role:      c.Role,
		})
	}
	return out, nil
}

// mapOpError translates the transport-agnostic *api.MirrorOpError into a
// huma error. Used by the mirror placement ops and by the org/project/repo
// delete handlers' in-cell ownership gate (Server.JurisdictionRedirect).
// The StatusMisdirectedRequest (421) case renders a custom body carrying
// home_core_url — the field the CLI's crossJurisRoundTripper reads to retry
// against the home core, which huma's default ErrorModel doesn't carry.
func mapOpError(err error) error {
	var oe *api.MirrorOpError
	if !errors.As(err, &oe) {
		return internalErr()
	}
	switch oe.Status {
	case http.StatusBadRequest:
		return badRequest(oe.Message)
	case http.StatusUnauthorized:
		return unauthorized(oe.Message)
	case http.StatusForbidden:
		return forbidden(oe.Message)
	case http.StatusNotFound:
		return notFound(oe.Message)
	case http.StatusConflict:
		return conflict(oe.Message)
	case http.StatusPreconditionFailed:
		return preconditionFailed(oe.Message)
	case http.StatusMisdirectedRequest:
		return &jurisdictionRedirectError{
			status:       oe.Status,
			Message:      oe.Message,
			HomeCoreURL:  oe.HomeCoreURL,
			Jurisdiction: oe.Jurisdiction,
		}
	case http.StatusBadGateway:
		return huma.Error502BadGateway(oe.Message)
	case http.StatusServiceUnavailable:
		return unavailable(oe.Message)
	default:
		return huma.NewError(oe.Status, oe.Message)
	}
}

// jurisdictionRedirectError renders a 421 cross-jurisdiction redirect whose
// JSON body carries home_core_url + jurisdiction. It implements
// huma.StatusError, so huma marshals this value (not its default
// ErrorModel) as the response body — matching the wire shape the CLI's
// mirror421Body parser expects.
type jurisdictionRedirectError struct {
	status       int
	Message      string `json:"error"`
	HomeCoreURL  string `json:"home_core_url"`
	Jurisdiction string `json:"jurisdiction,omitempty"`
}

func (e *jurisdictionRedirectError) Error() string  { return e.Message }
func (e *jurisdictionRedirectError) GetStatus() int { return e.status }

// ContentType keeps the 421 on application/problem+json, matching every
// other huma error (ErrorModel.ContentType). Without it this custom type
// would serialize as application/json and silently drift the RFC-9457
// label for just this endpoint.
func (e *jurisdictionRedirectError) ContentType(ct string) string {
	if ct == "application/json" {
		return "application/problem+json"
	}
	return ct
}

func registerMirrorOperations(api huma.API, svc *MirrorService) {
	tags := []string{"mirrors"}
	huma.Register(api, huma.Operation{
		OperationID: "listMirrors",
		Method:      http.MethodGet,
		Path:        "/mirrors",
		Summary:     "List mirrors visible to the caller",
		Tags:        tags, Security: securityAny,
		Errors: commonErrors,
	}, svc.ListMirrors)
	huma.Register(api, huma.Operation{
		OperationID: "listAvailableMirrors",
		Method:      http.MethodGet,
		Path:        "/mirrors/available",
		Summary:     "List GitHub repos the caller could onboard as mirrors",
		Tags:        tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusUnauthorized, http.StatusBadGateway, http.StatusServiceUnavailable),
	}, svc.ListAvailableMirrors)
	huma.Register(api, huma.Operation{
		OperationID: "getMirror",
		Method:      http.MethodGet,
		Path:        "/mirrors/{mirrorId}",
		Summary:     "Get mirror by id",
		Tags:        tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusNotFound),
	}, svc.GetMirror)
	huma.Register(api, huma.Operation{
		OperationID:   "createMirror",
		Method:        http.MethodPost,
		Path:          "/mirrors",
		Summary:       "Create GitHub mirror",
		DefaultStatus: http.StatusCreated,
		Tags:          tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusNotFound, http.StatusConflict, http.StatusPreconditionFailed, http.StatusMisdirectedRequest, http.StatusBadGateway, http.StatusServiceUnavailable),
	}, svc.CreateMirror)
	huma.Register(api, huma.Operation{
		OperationID: "deleteMirror",
		Method:      http.MethodDelete,
		Path:        "/mirrors",
		Summary:     "Delete a mirror by upstream coords + cluster host",
		Tags:        tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusForbidden, http.StatusNotFound, http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusMisdirectedRequest),
	}, svc.DeleteMirror)
	huma.Register(api, huma.Operation{
		OperationID: "listMirrorCollaborators",
		Method:      http.MethodGet,
		Path:        "/mirrors/collaborators",
		Summary:     "List the principals with access to a mirror (live GitHub-admin gated)",
		Tags:        tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusForbidden, http.StatusNotFound, http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusMisdirectedRequest),
	}, svc.ListCollaborators)
}

