// ListableMirrorRows returns every mirror placement in the account's repo#list
// set, across all jurisdictions. Mirrors are native repos (COR-434) with
// per-user repo#reader/#writer grants, so "mirrors I can see" is the repo#list
// SpiceDB reverse lookup, hydrated to rows by ID. list — not pull — because
// this is the enumeration permission: it omits the public_viewer (account:*)
// wildcard, so public mirrors the caller holds no grant on don't flood every
// account's listing. pull stays the authority for clone/token-exchange gates.
//
// This is deliberately NOT scoped to the contacted core's jurisdiction. The
// list set (SpiceDB) and the mirror_repos/clusters tables are global, and the
// user-facing list/get render only the cluster's PUBLIC host — so a single
// core can and should surface a user's mirrors in every jurisdiction. (The
// jurisdiction-scoped MirrorReposListAll stays for the admin listing, which
// needs the cluster's private internal_url and so can only act on local
// clusters.) Listing from the EU core must show your US mirrors too.
//
// Both reader and writer grants surface (writer resolves list). An account
// with no grant sees nothing. Suspended placements are excluded — they're
// circuit-broken. Hydrating by the listable IDs keeps this O(your-mirrors),
// not a scan of every mirror row.
func (s *Server) ListableMirrorRows(ctx context.Context, accountID model.AccountID) ([]MirrorListRow, error) {
	// No mirror store (or no authz) → nothing to return. Short-circuit before
	// the SpiceDB lookup so an unconfigured deployment stays quiet rather than
	// paying an authz round-trip — whose rows we couldn't hydrate anyway — and
	// risking a 500 on a SpiceDB hiccup.
	if s.authz == nil || s.mirrorRepos == nil {
		return nil, nil
	}
	ids, err := s.authz.LookupResources(ctx, "repo", "list", "account", accountID.String())
	if err != nil {
		return nil, fmt.Errorf("lookup listable repos: %w", err)
	}
	repoIDs := make([]model.RepoID, 0, len(ids))
	for _, id := range ids {
		rid, perr := model.ParseRepoID(id)
		if perr != nil {
			// SpiceDB may return ids that aren't repo ULIDs; they can't name a
			// mirror row, so skip rather than fail the whole listing.
			continue
		}
		repoIDs = append(repoIDs, rid)
	}
	if len(repoIDs) == 0 {
		return nil, nil
	}

	// Follower read (COR-371 sweep): pure display hydration, and the listable
	// id set routinely includes native repos with no mirror row, so short
	// results are normal — exactly the error-only-fallback contract. A
	// placement created inside the ~4.8s staleness window is absent from the
	// listing for a few seconds; a just-flipped suspended_at lags equally
	// briefly (the actual pull gate reads is_private/suspension fresh).
	rows, err := s.MirrorReposListByIDsFollowerRead(ctx, repoIDs)
	if err != nil {
		return nil, err
	}
	out := make([]MirrorListRow, 0, len(rows))
	for _, r := range rows {
		if r.SuspendedAt != nil {
			continue // circuit-broken
		}
		out = append(out, r)
	}
	return out, nil
}

// ListableMirrorRowsPage is the keyset-paginated form of ListableMirrorRows. The
// SpiceDB list lookup is unpaginated (it returns the caller's accessible id set,
// bounded by their grants — same trade-off as ListProjects); the Postgres fetch
// is the keyset page. nextCursor is the underlying (pre-suspended-filter) page

		}
		return nil, translatePublishError(r, err)
	}

	return r, nil
}

// SeedGrant is the creator's initial role grant folded into
// RegisterMirrorAsNativeRepo's SpiceDB write.
type SeedGrant struct {
	GranteeType string // "account"
	GranteeID   model.ID
	Role        string // "writer" or "reader"
}

// RegisterMirrorAsNativeRepo registers an already-placed mirror ULID as a
// native repo under its mirrors project, idempotently. Unlike AdoptRepo (the
// admin-import path, which returns ErrAlreadyExists on a re-adopt) it converges
// on retry: the row insert is ON CONFLICT (id) DO NOTHING and the SpiceDB
// project edge + registry row are re-asserted unconditionally, so a call that
// died partway through self-heals when mirror-create retries. `created` reports
// whether this call inserted the regional row.
//
// The only sanctioned writer into a gh:mirrors:* project; ordinary repo
// creation is blocked from those projects at the API edge.
//
// Born active: the mirror's storage already exists (the data-plane Provision
// ran first), so there is no provisioning state to traverse. A failure after
// the row inserts but before publish leaves an active-but-unpublished row that
// the next retry clears. The mirror serves over /gh/ throughout — the registry
// row and SpiceDB edge are governance metadata, not part of data-plane
// resolution.
//
// The SpiceDB write folds everything the placement needs into ONE
// WriteRelationships — from a region far from the authz-writer each write is
// a full cross-region round trip, so batching them is the whole game: the
// repo's structural edges, the seeds (on the user path, the creator's
// grant), the mirrors
// project's system tuples (the self-heal for a project orphaned by a failed
// create, previously a standalone write on the resource-store find path), and
// the linked org's platform tuple (org-owned projects — same self-heal for
// the owner-less COR-432 org). Idempotent throughout (TOUCH/reconcile
// semantics).
func (s *Store) RegisterMirrorAsNativeRepo(ctx context.Context, id model.RepoID, project *model.Project, name, clusterSlug string, seeds []SeedGrant) (created bool, err error) {
	r := &model.Repo{
		ID:              id,
		OwningProjectID: project.ID,
		Name:            name,
		State:           model.RepoStateActive,
		ClusterSlug:     clusterSlug,
		ObjectFormat:    defaultObjectFormat(""),
	}

	tag, err := s.pool.Exec(ctx,
		`INSERT INTO repos (id, owning_project_id, name, state, cluster_slug, object_format)
		 VALUES ($1, $2, $3, $4, $5, $6)
		 ON CONFLICT (id) DO NOTHING`,
		r.ID, r.OwningProjectID, r.Name, r.State, nullableString(clusterSlug), r.ObjectFormat,
	)
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			// ON CONFLICT (id) already absorbs an id collision, so a
			// unique_violation here is the (owning_project_id, lower(name))
			// index: a different repo already holds this name in the mirrors
			// project. Only reachable on user-owned mirrors projects, where
			// the owner can create native repos.
			return false, fmt.Errorf("repo %q in project %s: %w", name, project.ID, ErrNameConflict)
		}
		return false, fmt.Errorf("register mirror as native repo: %w", err)
	}
	created = tag.RowsAffected() > 0

	// Re-assert unconditionally — both writes are idempotent (SpiceDB TOUCH,
	// registry upsert), so this repairs a half-applied promotion regardless
	// of whether we just inserted the row. The structural edges, project/org
	// system tuples, and every seed grant go in one WriteRelationships call.
	grants := make([]authz.RepoGrant, len(seeds))
	for i, sd := range seeds {
		grants[i] = authz.RepoGrant{GranteeType: sd.GranteeType, GranteeID: sd.GranteeID, Role: sd.Role}
	}
	if err = s.authz.MirrorPlacementRegistered(ctx, authz.MirrorPlacement{
		RepoID:           r.ID,
		ProjectID:        project.ID,
		ProjectOwnerType: project.OwnerType,
		ProjectOwnerID:   project.OwnerID,
		Grants:           grants,
	}); err != nil {
		return false, fmt.Errorf("authz mirror placement registered: %w", err)
	}
	if err := s.registry.PublishRepo(ctx, s.registrationFor(r)); err != nil {
		return false, translatePublishError(r, err)
	}
	return created, nil
}

// MarkRepoActive re-asserts the registry row and flips state to active. The
// row was normally published at reservation (StartProvisionRepo), but a crash
// between the regional insert and that publish leaves it missing — publishing
// before the flip keeps the invariant `state='active' ⇒ registered`: a
// publish failure leaves state='provisioning' and the reconciler retries both
// steps (both are idempotent).
//
// Race recovery: if the UPDATE affects 0 rows because a concurrent
// MarkRepoFailed changed the state, the already-succeeded publish would
// leave an orphan registry row. Re-read the state and unpublish if it's
// now 'failed' to restore the invariant.
func (s *Store) MarkRepoActive(ctx context.Context, repoID model.RepoID) error {
	r, err := s.GetRepo(ctx, repoID)
	if err != nil {
		return err
	}
	if r.State != model.RepoStateProvisioning {
		return fmt.Errorf("repo %s: %w", repoID, ErrNotFound)
	}

	if err := s.registry.PublishRepo(ctx, s.registrationFor(r)); err != nil {
		return translatePublishError(r, err)
	}
	cmd, err := s.pool.Exec(ctx,
		`UPDATE repos SET state='active', provision_reason=NULL
		 WHERE id=$1 AND state='provisioning'`,
		repoID)
	if err != nil {
		return fmt.Errorf("mark repo active: %w", err)
	}
	if cmd.RowsAffected() == 0 {
		s.compensatePublishOnConcurrentFailure(ctx, repoID)
		return fmt.Errorf("repo %s: %w", repoID, ErrNotFound)
	}
	return nil
}

// compensatePublishOnConcurrentFailure cleans up an orphan registry row when
// another reconciler flipped the state to 'failed' between our PublishRepo
// and state UPDATE. Best-effort: any error here is logged and swallowed so
// the caller still sees the original ErrNotFound for the missed flip.
func (s *Store) compensatePublishOnConcurrentFailure(ctx context.Context, repoID model.RepoID) {
	r, err := s.GetRepo(ctx, repoID)
	if err != nil || r.State != model.RepoStateFailed {
		return
	}
	if err := s.registry.UnpublishRepo(ctx, repoID); err != nil && !errors.Is(err, registry.ErrNotFound) {
		slogutil.Error(ctx, "mark-active race: unpublish orphan failed",
			slog.String("repo_id", repoID.String()),
			slog.String("error", err.Error()))
	}
}

