type Store struct {
	read  storeReadClient
	write *authzed.Client
	// fullyConsistentReadsForTest routes the stale-tolerant reads through
	// fully_consistent instead of minimize_latency. Set ONLY by
	// NewStoreForTest; prod leaves it false so reads stay region-local. The
	// zero value preserves the prod policy, so a bare Store{read: fake} in the
	// consistency-policy tests still exercises minimize_latency.
	fullyConsistentReadsForTest bool
}

var _ Service = (*Store)(nil)

// NewStore builds a Store where reads and writes share one SpiceDB client.
func NewStore(client *authzed.Client) *Store {
	return &Store{read: client, write: client}
}

// NewStoreRW builds a Store that routes reads to one SpiceDB client and writes
// to another — reads to a read-only replica, writes to the read-write endpoint.
func NewStoreRW(read, write *authzed.Client) *Store {
	return &Store{read: read, write: write}
}

// NewStoreForTest builds a single-client Store whose stale-tolerant reads run
// fully consistent, so write-then-read assertions are deterministic instead of
// racing SpiceDB's revision-quantization window — 1ms in dev/CI, but -race
// widens the write→read gap well past it. The vulnerable direction is
// revoke-then-assert-deny: a stale ALLOW is served as-is (only denies get the
// fully-consistent re-check), so any suite that revokes and asserts flakes
// under NewStore. Convention: EVERY test setup that builds a Store against
// the shared SpiceDB uses this constructor. The prod minimize_latency policy
// keeps its coverage in store_consistency_test.go (fake client) and
// reader_integration_test.go (real SpiceDB, deliberately NewReaderFromClient).
// TEST ONLY: panics outside a `go test` binary — fully-consistent reads in a
// prod pathway would silently defeat the minimize_latency policy (see Store)
// that EU/AU latency depends on.
func NewStoreForTest(client *authzed.Client) *Store {
	if !testing.Testing() {
		panic("authz.NewStoreForTest is test-only: its fully-consistent reads defeat the minimize_latency read policy prod depends on — use NewStore/NewStoreRW")
	}
	return &Store{read: client, write: client, fullyConsistentReadsForTest: true}
}

// staleRead is the consistency for the Store's stale-tolerant reads:
// minimize_latency in prod, fully_consistent under NewStoreForTest. The deny
// re-checks (Can, HasPublicAccess) call fullyConsistent() directly and are
// unaffected.
